#include <string>

class Solution {
public:
    int minOpsToSortBinaryString(std::string s) {
        for (size_t i = 0; i + 1 < s.size(); ++i) {
            if (s[i] > s[i + 1]) return 1;
        }
        return 0;
    }
};

class Solution {
    public int minOpsToSortBinaryString(String s) {
        for (int i = 0; i + 1 < s.length(); i++) {
            if (s.charAt(i) > s.charAt(i + 1)) return 1;
        }
        return 0;
    }
}

